async function saveCommand(command){if(busy)throw Error('A save is already in progress.');if(!state)throw Error('Load the calendar before saving.');busy=true;const id='CMD-'+crypto.randomUUID();try{let next;if(demo)next=M.apply(state,{...command,commandId:id},{id:'demo-superintendent',name:'Demo Superintendent'});else next=(await request('POST',{revision:state.revision,command:{...command,commandId:id}})).state;state=M.validate(next,course.id);render();return state;}catch(e){if(e.status===409){await load(true);throw Error(e.message+' Your form has been kept. If this plan changed, close and reopen it before saving.');}throw e;}finally{busy=false;}}
